import {mountShell} from '../shared/shell.js?v=0.20.0';
import {escapeHtml as e,writeStore,downloadText} from '../shared/utils.js?v=0.20.0';
import {lineChart} from '../model-kit/chart.js?v=0.20.0';
import {create,simulate,assess,edges,OFFSETS,stateAt} from './engine.js?v=0.20.0';
import {NETWORKS,KEY,switchNetwork,toggleLink,placement,differences,positions,validateBundle,initialBundle,portable,parse,markdown} from './plans.js?v=0.20.0';
mountShell({active:'adoption'});
const app=document.querySelector('#app'),clone=structuredClone,f=x=>Number(x).toFixed(1),name=i=>String(i+1).padStart(2,'0');
let b=initialBundle(),past=[],message='',pending=null,paused=false,recovery=null,suppressClick=false;
try{const raw=localStorage.getItem(KEY);if(raw){recovery=raw;b=validateBundle(JSON.parse(raw));recovery=null;}}catch{paused=true;message='Saved work needs recovery. Saving is paused until you choose to replace it.';}
function save(){if(paused)return;if(!writeStore(KEY,b)){message='Storage unavailable. Export to keep this experiment.';app.querySelector('.status').textContent=message;}}
function change(fn,msg){const before=clone(b);try{fn();b=validateBundle(b);past.push(before);past=past.slice(-40);b.round=0;pending=null;message=msg||'Starting conditions changed. Both trajectories are replayed.';save();render();}catch(error){b=before;message=error.message;render();}}
const networkNote=s=>({groups:s.bridge?'Two dense groups with two additional cross-group links.':'Two separate groups: 30 links, five partners per person.',mixed:'30 links and five partners per person, as in the unbridged groups; the partner mix changes.',hub:'11 links. Person 01 connects to everyone; each other person has one partner.',custom:'Your edited undirected links. Isolated people have no coordination utility.'}[s.network||'groups']);
function render(){const active=document.activeElement,focusId=active?.id,scroll=app.querySelector('.network-wrap')?.scrollLeft||0,tableScroll=app.querySelector('.outcome-scroll')?.scrollLeft||0,open=[...app.querySelectorAll('details[open][id]')].map(x=>x.id);const s=b.s,r=simulate(s),p=b.baseline?simulate(b.baseline):null,maxRound=Math.max(r.rounds,p?.rounds||0);b.round=Math.min(b.round,maxRound);const now=stateAt(r,b.round),pinned=p?stateAt(p,b.round):null,rows=assess(s,now),row=rows[b.selected],pos=positions(s),links=edges(s),diff=differences(s,b.baseline),rounds=Array.from({length:maxRound+1},(_,i)=>i);app.innerHTML=`
<section class="surface"><div class="toolbar"><button class="primary" id="step" ${b.round>=maxRound?'disabled':''}>Step one round</button><button id="run">Run to outcome</button><button id="rewind">Back to pilot</button><button id="pin">${p?'Replace pinned plan':'Pin this plan'}</button><button id="undo" ${past.length?'':'disabled'}>Undo</button><button id="reset">Reset</button></div>
<div class="network-settings"><label for="network-select">Coordination network<select id="network-select">${Object.entries(NETWORKS).map(([k,v])=>`<option value="${k}" ${k===(s.network||'groups')?'selected':''} ${k==='custom'?'disabled':''}>${v}</option>`).join('')}</select></label><div><p>${networkNote(s)}</p><span class="hint">${links.length} connections · ${12-rows.filter(x=>x.neighbours.length).length} isolated people · personal differences stay fixed</span></div></div>
<div class="toolbar modes" role="group" aria-label="Network interaction"><button data-mode="pilot" aria-pressed="${b.mode==='pilot'}">Choose pilot</button><button data-mode="inspect" aria-pressed="${b.mode==='inspect'}">Inspect people</button><button data-mode="connect" aria-pressed="${b.mode==='connect'}">Edit connections</button></div><p class="status" role="status">${e(message||(b.mode==='pilot'?'Tap people to add or remove them from the starting pilot.':b.mode==='inspect'?'Select a person to inspect their partners and next choice.':'Choose two people, or drag between them, to add or remove a connection.'))}</p><p class="scroll-hint">Scroll sideways to reach the whole network ↔. Numbered controls also work with the keyboard.</p>
<div class="network-wrap" tabindex="0" role="region" aria-label="Scrollable twelve-person network"><div class="network ${b.mode==='connect'?'connecting':''}"><svg aria-hidden="true" viewBox="0 0 100 100" preserveAspectRatio="none">${links.map(([a,c])=>`<line class="${a===b.selected||c===b.selected?'adjacent':''}" x1="${pos[a].x}" y1="${pos[a].y}" x2="${pos[c].x}" y2="${pos[c].y}"></line>`).join('')}<line id="draft-link" class="draft-link" hidden></line></svg>${(s.network==='custom'?(s.layout||'groups'):(s.network||'groups'))==='groups'?'<span class="cluster one">Cohort A</span><span class="cluster two">Cohort B</span>':''}${pos.map((point,i)=>`<button id="node-${i}" class="person ${now[i]?'adopted':''} ${s.seeds.includes(i)?'seed':''} ${i===b.selected?'selected':''} ${i===pending?'pending':''}" data-person="${i}" style="left:${point.x}%;top:${point.y}%" aria-pressed="${b.mode==='pilot'?s.seeds.includes(i):b.mode==='inspect'?b.selected===i:pending===i}" aria-label="Person ${name(i)}, ${now[i]?'using new':'using old'}, ${s.seeds.includes(i)?'pilot':'not pilot'}; ${b.mode==='pilot'?'toggle pilot membership':b.mode==='inspect'?'inspect choice':'choose connection endpoint'}"><b>${name(i)}</b><small>${s.seeds.includes(i)?'Pilot':now[i]?'New':'Old'}</small></button>`).join('')}</div></div>
<p class="hint">Filled = using new · outlined = pilot · highlighted lines = selected person’s partners. Cohorts A (01–06) and B (07–12) retain the same people across networks.</p>
${b.mode==='connect'?`<div class="connection-editor"><label>First person<select id="link-from">${pos.map((_,i)=>`<option value="${i}" ${i===(pending??b.selected)?'selected':''}>${name(i)}</option>`).join('')}</select></label><label>Second person<select id="link-to">${pos.map((_,i)=>`<option value="${i}" ${i===((pending??b.selected)+1)%12?'selected':''}>${name(i)}</option>`).join('')}</select></label><button id="toggle-link">Add / remove connection</button></div>`:''}
<div class="toolbar placement"><label>Pilot size<input id="pilot-count" type="number" min="0" max="12" value="${s.seeds.length}"></label><button data-placement="concentrate">Concentrate in cohort A</button><button data-placement="spread">Spread across cohorts</button><button data-placement="connected">Most connected people</button><button id="clear">Clear pilot</button>${(s.network||'groups')==='groups'?`<button id="bridge" aria-pressed="${s.bridge}">${s.bridge?'Remove':'Add'} two links between groups</button>`:''}</div><p class="hint">Placement buttons keep pilot size unchanged. “Most connected” uses partner count, then person number to break ties. Changing pilot size starts with an even spread.</p>
<div class="field timeline"><label for="round">Inspect round <output>${b.round} / ${maxRound}</output></label><input id="round" type="range" min="0" max="${maxRound}" value="${b.round}"></div></section>
<section class="metrics"><div class="metric"><span>Using new now</span><strong>${now.filter(Boolean).length}/12</strong><small>At round ${b.round}${pinned?` · pinned ${pinned.filter(Boolean).length}/12`:''}</small></div><div class="metric"><span>Starting pilot</span><strong>${s.seeds.length}</strong><small>${s.hold?'Stays committed':'May switch back'}</small></div><div class="metric"><span>Cohort A / cohort B using new</span><strong>${now.slice(0,6).filter(Boolean).length} / ${now.slice(6).filter(Boolean).length}</strong><small>Each cohort contains six people</small></div><div class="metric"><span>Current trajectory</span><strong>${r.status==='stable'?'Stable':r.status==='cycle'?'Cycle':'Changing'}</strong><small>${r.status==='cycle'?`Repeats every ${r.cycleLength} rounds from round ${r.cycleStart}`:`${r.rounds} rounds simulated`}</small></div></section>
${p?`<section class="comparison-note"><h2>What changed from the pinned plan?</h2><p>${diff.length?e(diff.join(' · ')):'Nothing: the two plans match.'}</p><p class="hint">Same twelve people and fixed personal differences. Each row below compares the same round; stable states persist and detected cycles repeat. ${diff.some(x=>!['pilot location','pilot size and location','connections'].includes(x))?'Utility or commitment assumptions also differ.':''}</p></section>`:''}
<div class="split"><section class="surface"><h2>What makes switching worthwhile?</h2><div class="fields">${[['benefit','Standalone benefit',0,12,.5],['coordination','Value of coordinating',0,12,.5],['switching','One-time switching friction',0,6,.5],['compatibility','New works with old',0,1,.1]].map(([k,l,min,max,step])=>`<div class="field"><label for="${k}">${l}<output>${f(s[k])}</output></label><input data-param="${k}" id="${k}" type="range" min="${min}" max="${max}" step="${step}" value="${s[k]}"></div>`).join('')}</div><label class="hold"><input type="checkbox" id="hold" ${s.hold?'checked':''}> Pilot participants stay committed</label><p>Compatibility gives new users some coordination value with old users. Old users still benefit only from old partners.</p></section>
<section class="surface" id="inspector"><h2>Why does this person switch—or stay?</h2><label for="person-select">Inspect person<select id="person-select">${pos.map((_,i)=>`<option value="${i}" ${i===b.selected?'selected':''}>${name(i)} · cohort ${i<6?'A':'B'}</option>`).join('')}</select></label><p class="partners">Partners: ${row.neighbours.length?row.neighbours.map(i=>`${name(i)} (${now[i]?'new':'old'})`).join(', '):'none; both coordination terms are zero'}</p><table class="reason"><tr><th>Partners using new</th><td>${row.neighbours.length?`${row.neighbours.filter(i=>now[i]).length}/${row.neighbours.length} · ${Math.round(row.share*100)}%`:'No partners'}</td></tr><tr><th>New utility</th><td>${f(row.newValue)}</td></tr><tr><th>Old utility</th><td>${f(row.oldValue)}</td></tr><tr><th>New minus old</th><td>${f(row.gain)}</td></tr><tr><th>Cost to change either way</th><td>${f(s.switching)}</td></tr></table><p><strong>${row.held?'Stays new as a committed pilot participant.':row.next===row.current?`Stays with ${row.current?'new':'old'}; changing does not beat friction.`:`Switches to ${row.next?'new':'old'}; the gain exceeds friction.`}</strong></p><p class="hint">Personal standalone benefit: ${f(row.personal)}. Decisions are simultaneous, using partners before the round.</p></section></div>
<section class="surface"><h2>Who adopts at round ${b.round}?</h2><p>Equal totals can hide different people. ${p?'Highlighted rows differ from the pinned plan.':'Pin a plan to compare membership as well as totals.'}</p><p class="scroll-hint">Scroll sideways through the comparison ↔.</p><div class="outcome-scroll" tabindex="0" role="region" aria-label="Adoption by person"><table class="outcome-table"><colgroup><col style="width:115px"><col style="width:85px">${p?'<col style="width:85px">':''}<col style="width:80px"><col style="width:160px"><col style="width:140px"></colgroup><thead><tr><th>Person</th><th>Current</th>${p?'<th>Pinned</th>':''}<th>Partners</th><th>First new (whole run)</th><th>Next choice</th></tr></thead><tbody>${now.map((v,i)=>{const first=r.history.findIndex(h=>h[i]);return `<tr class="${pinned&&v!==pinned[i]?'different':''}"><th><button id="inspect-${i}" data-inspect="${i}">${name(i)} · ${i<6?'A':'B'}</button>${s.seeds.includes(i)?'<span class="pilot-label">Pilot</span>':''}</th><td>${v?'New':'Old'}</td>${pinned?`<td>${pinned[i]?'New':'Old'}</td>`:''}<td>${rows[i].neighbours.length}</td><td>${first<0?'Not reached':first===0?'Pilot':`Round ${first}`}</td><td>${rows[i].held?'Held pilot':rows[i].next===v?'Stay':rows[i].next?'Switch to new':'Switch to old'}</td></tr>`;}).join('')}</tbody></table></div></section>
<section class="surface"><h2>Adoption over rounds</h2><div class="chart" role="img" aria-label="Adoption at matching rounds, current and pinned plans">${lineChart([{values:rounds.map(t=>stateAt(r,t).filter(Boolean).length)},...(p?[{values:rounds.map(t=>stateAt(p,t).filter(Boolean).length),color:'var(--muted)',dashed:true}]:[])],{min:0,max:12,labels:['Pilot',`Round ${maxRound}`],cursor:b.round})}</div><p class="hint">Solid: current. Dashed: pinned. Repeating cycles are extended to the same displayed round, not treated as stable outcomes.</p></section>
<section class="surface"><label for="decision">Which pilot or connection would you try, and what assumption needs checking?</label><textarea id="decision" rows="3" maxlength="20000">${e(b.decision)}</textarea></section>
<details id="mechanism"><summary>Mechanism and limits</summary><p>Let q be the share of a person’s partners using new. New utility = personal benefit + coordination × [q + compatibility × (1 − q)]. Old utility = coordination × (1 − q). With no partners, both coordination terms are zero. A change happens only when the other choice exceeds current utility by more than friction. Ties keep the current choice; held pilots stay new regardless.</p><p>Personal benefit adds fixed differences in person order: ${OFFSETS.join(', ')}. Presets change who coordinates with whom; the mixed ring and unbridged groups each have 30 links and five partners per person. Hub and custom networks can also change partner counts. Decisions update simultaneously until stable, a cycle repeats, or 24 rounds pass. Costs affect switching decisions; the model does not accumulate money or welfare.</p><p>Fictional, deterministic coordination with complete local information, fixed preferences and no persuasion, uncertainty, budget or learning. Compatibility is one-way.</p></details>${paused?'<div class="recovery"><p>Saving is paused to protect existing work.</p><button id="recover">Download recovery copy</button><button id="resume">Save this experiment instead</button></div>':''}<p class="local-note">Plans, connections, inspection round and decision save in this browser. Export a copy to keep them.</p>`;
 bind();open.forEach(id=>document.getElementById(id)?.setAttribute('open',''));app.querySelector('.network-wrap').scrollLeft=scroll;app.querySelector('.outcome-scroll').scrollLeft=tableScroll;if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}
function editConnection(a,c){if(a===c){pending=null;message='Choose two different people.';render();return;}change(()=>{b.s=toggleLink(b.s,a,c);b.selected=c;},`Connection ${name(a)}–${name(c)} toggled. The edited network is now your own.`);}
function bind(){
 app.querySelectorAll('[data-person]').forEach(el=>el.onclick=()=>{if(suppressClick)return;const id=+el.dataset.person;if(b.mode==='pilot')change(()=>{b.selected=id;b.s.seeds=b.s.seeds.includes(id)?b.s.seeds.filter(x=>x!==id):[...b.s.seeds,id];},'Pilot changed. Replay starts from these people.');else if(b.mode==='inspect'){b.selected=id;message=`Person ${name(id)} selected. Their partners and next choice appear below.`;save();render();}else if(pending===null){pending=id;b.selected=id;message=`Person ${name(id)} selected. Choose another person to toggle their connection.`;render();}else editConnection(pending,id);});
 app.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{b.mode=el.dataset.mode;pending=null;message='';save();render();});
 app.querySelector('#network-select').onchange=event=>change(()=>b.s=switchNetwork(b.s,event.target.value),'Network changed; pilot and utility assumptions kept.');app.querySelector('#toggle-link')?.addEventListener('click',()=>editConnection(+app.querySelector('#link-from').value,+app.querySelector('#link-to').value));
 app.querySelectorAll('[data-placement]').forEach(el=>el.onclick=()=>change(()=>b.s=placement(b.s,el.dataset.placement),'Pilot placement changed; size, network and utility assumptions kept.'));app.querySelector('#pilot-count').onchange=event=>change(()=>b.s=placement(b.s,'spread',+event.target.value),'Pilot size changed, spread across the two cohorts.');
 app.querySelectorAll('[data-param]').forEach(el=>el.onchange=()=>change(()=>b.s[el.dataset.param]=+el.value));app.querySelector('#hold').onchange=event=>change(()=>b.s.hold=event.target.checked);app.querySelector('#bridge')?.addEventListener('click',()=>change(()=>b.s.bridge=!b.s.bridge));app.querySelector('#clear').onclick=()=>change(()=>b.s.seeds=[]);
 app.querySelector('#step').onclick=()=>{b.round++;save();render();};app.querySelector('#run').onclick=()=>{b.round=Math.max(simulate(b.s).rounds,b.baseline?simulate(b.baseline).rounds:0);save();render();};app.querySelector('#rewind').onclick=()=>{b.round=0;save();render();};app.querySelector('#round').onchange=event=>{b.round=+event.target.value;save();render();};app.querySelector('#person-select').onchange=event=>{b.selected=+event.target.value;save();render();};app.querySelectorAll('[data-inspect]').forEach(el=>el.onclick=()=>{b.selected=+el.dataset.inspect;b.mode='inspect';save();render();document.querySelector('#inspector').scrollIntoView({block:'start'});document.querySelector('#person-select').focus({preventScroll:true});});
 app.querySelector('#pin').onclick=()=>change(()=>b.baseline=clone(b.s),'Plan pinned. Its assumptions remain fixed; comparison lists every difference.');app.querySelector('#undo').onclick=()=>{if(past.length){b=past.pop();pending=null;message='Last change undone.';save();render();}};app.querySelector('#reset').onclick=()=>change(()=>b.s=create(),'Initial situation restored; pinned plan kept.');app.querySelector('#decision').onchange=event=>{past.push(clone(b));past=past.slice(-40);b.decision=event.target.value;app.querySelector('#undo').disabled=false;save();};
 app.querySelector('#recover')?.addEventListener('click',()=>downloadText('adoption-recovery.json',recovery||JSON.stringify(b),'application/json'));app.querySelector('#resume')?.addEventListener('click',()=>{paused=false;recovery=null;message='This experiment is saved in this browser.';save();render();});
 const network=app.querySelector('.network');let drag=null;const line=network.querySelector('#draft-link');const clean=()=>{line.setAttribute('hidden','');network.querySelectorAll('.link-target').forEach(x=>x.classList.remove('link-target'));drag=null;};network.onpointerdown=event=>{const el=event.target.closest('[data-person]');if(b.mode!=='connect'||!el||event.button!==0)return;drag={id:+el.dataset.person,x:event.clientX,y:event.clientY,moved:false,pointer:event.pointerId};};network.onpointermove=event=>{if(!drag)return;if(Math.hypot(event.clientX-drag.x,event.clientY-drag.y)<8&&!drag.moved)return;event.preventDefault();if(!drag.moved)network.setPointerCapture(event.pointerId);drag.moved=true;const rect=network.getBoundingClientRect(),pos=positions(b.s)[drag.id];line.removeAttribute('hidden');line.setAttribute('x1',pos.x);line.setAttribute('y1',pos.y);line.setAttribute('x2',(event.clientX-rect.left)/rect.width*100);line.setAttribute('y2',(event.clientY-rect.top)/rect.height*100);network.querySelectorAll('.link-target').forEach(x=>x.classList.remove('link-target'));document.elementsFromPoint(event.clientX,event.clientY).find(x=>x.matches?.('[data-person]'))?.classList.add('link-target');};network.onpointerup=event=>{if(!drag)return;const d=drag,target=document.elementsFromPoint(event.clientX,event.clientY).map(x=>x.closest?.('[data-person]')).find(Boolean);if(network.hasPointerCapture(event.pointerId))network.releasePointerCapture(event.pointerId);clean();if(d.moved){suppressClick=true;setTimeout(()=>suppressClick=false,0);if(target)editConnection(d.id,+target.dataset.person);}};network.onpointercancel=clean;
}
document.querySelector('#export').onclick=()=>downloadText('adoption-gap.md',markdown(b),'text/markdown');document.querySelector('#json').onclick=()=>downloadText('adoption-gap.json',portable(b),'application/json');document.querySelector('#import').onclick=()=>document.querySelector('#import-file').click();document.querySelector('#import-file').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error('Choose a file under 1 MB.');const next=parse(await file.text());past.push(clone(b));past=past.slice(-40);b=next;pending=null;message='Experiment imported. Undo restores the previous plan.';save();render();}catch(error){message=error.message;render();}event.target.value='';};window.addEventListener('pagehide',()=>{b.decision=app.querySelector('#decision')?.value||b.decision;save();});window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue!==JSON.stringify(b)){paused=true;recovery=event.newValue;message='Another tab changed this experiment. Saving here is paused.';render();}});render();
